package com.commercecore.payment;import jakarta.persistence.*;import java.time.*;import java.util.*;
@Entity @Table(name="payment_events") public class PaymentEvent {@Id@GeneratedValue(strategy=GenerationType.UUID)UUID id;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="payment_id",nullable=false)Payment payment;@Enumerated(EnumType.STRING)@Column(name="event_type",nullable=false)PaymentEventType eventType;@Enumerated(EnumType.STRING)@Column(name="from_status")PaymentStatus fromStatus;@Enumerated(EnumType.STRING)@Column(name="to_status")PaymentStatus toStatus;@Column(name="provider_reference")String providerReference;@Column(name="failure_code")String failureCode;@Column(name="occurred_at",nullable=false)Instant occurredAt;protected PaymentEvent(){}public PaymentEvent(Payment p,PaymentEventType e,PaymentStatus f,PaymentStatus t,String ref){payment=p;eventType=e;fromStatus=f;toStatus=t;providerReference=ref;occurredAt=Instant.now();} }
